// DecompileSecurePageHostAccess.java
//@category SP11.Camera
import ghidra.app.script.GhidraScript; import ghidra.app.decompiler.*; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*; import ghidra.program.model.data.*; import java.io.*; import java.util.*;
public class DecompileSecurePageHostAccess extends GhidraScript {
 public void run() throws Exception { String[] a=getScriptArgs(); PrintWriter p=new PrintWriter(new FileOutputStream(a[0])); String[] names={"SkmiAllocatePhysicalPage","SkmiProtectPageRange","SkmiZeroSinglePage","SkmiPfnClassToContents","SkmiFreePhysicalPage"}; SymbolTable st=currentProgram.getSymbolTable(); FunctionManager fm=currentProgram.getFunctionManager(); DecompInterface di=new DecompInterface(); di.openProgram(currentProgram); for(String n:names){List<Symbol> syms=st.getGlobalSymbols(n); p.println("=== SYMBOL "+n+" count="+syms.size()+" ==="); for(Symbol s:syms){Function f=fm.getFunctionAt(s.getAddress()); if(f==null)f=fm.getFunctionContaining(s.getAddress()); p.println("symbol="+s.getName()+" addr="+s.getAddress()+" function="+(f==null?"null":f.getName())); if(f!=null){p.println("sig="+f.getSignature()); DecompileResults dr=di.decompileFunction(f,180,monitor); if(dr!=null&&dr.decompileCompleted()&&dr.getDecompiledFunction()!=null)p.println(dr.getDecompiledFunction().getC());}}}
 Symbol v=st.getGlobalSymbol("SkmiVtlPageAccess",null); if(v!=null){p.println("=== DATA SkmiVtlPageAccess addr="+v.getAddress()+" ==="); Data d=currentProgram.getListing().getDataAt(v.getAddress()); p.println(d==null?"no-data":d.toString()); for(int i=0;i<32;i++){ try { byte b=currentProgram.getMemory().getByte(v.getAddress().add(i)); p.printf("%02x%s",b&0xff,(i%16==15)?"\n":" "); } catch(Exception e){break;} } }
 di.dispose(); p.close(); }
}
